import { useState, useEffect } from "react";
import { Container, Row, Col } from "react-bootstrap";
import headerImg from "../assets/img/work.webp";
import { ArrowRightCircle } from 'react-bootstrap-icons';
import 'animate.css';
import TrackVisibility from 'react-on-screen';

export const Banner = () => {
  const [loopNum, setLoopNum] = useState(0);
  const [isDeleting, setIsDeleting] = useState(false);
  const [text, setText] = useState('');
  const [delta, setDelta] = useState(300 - Math.random() * 100);
  const [index, setIndex] = useState(1);
  const toRotate = [ "Forntend Developer", "Java Developer", "Software Developer" ];
  const period = 2000;

  useEffect(() => {
    let ticker = setInterval(() => {
      tick();
    }, delta);

    return () => { clearInterval(ticker) };
  }, [text])

  const tick = () => {
    let i = loopNum % toRotate.length;
    let fullText = toRotate[i];
    let updatedText = isDeleting ? fullText.substring(0, text.length - 1) : fullText.substring(0, text.length + 1);

    setText(updatedText);

    if (isDeleting) {
      setDelta(prevDelta => prevDelta / 2);
    }

    if (!isDeleting && updatedText === fullText) {
      setIsDeleting(true);
      setIndex(prevIndex => prevIndex - 1);
      setDelta(period);
    } else if (isDeleting && updatedText === '') {
      setIsDeleting(false);
      setLoopNum(loopNum + 1);
      setIndex(1);
      setDelta(500);
    } else {
      setIndex(prevIndex => prevIndex + 1);
    }
  }

  const handleClick = () => {
    const connectSection = document.getElementById("connect");
    if (connectSection) {
      connectSection.scrollIntoView({ behavior: 'smooth' });
    }
  };

  return (
    <section className="banner" id="home">
      <Container>
        <Row className="aligh-items-center">
          <Col xs={12} md={6} xl={7}>
            {/* <TrackVisibility>
              {({ isVisible }) =>
              <div className={isVisible ? "animate__animated animate__fadeIn" : ""}>
                <span className="tagline">Welcome back!</span>
                  <h1>{`Hi! I'm Hari Haran,`} <span className="txt-rotate" dataPeriod="1000" data-rotate='[ "Full Stack Java Developer", "Java Developer", "Software Developer"]'><span className="wrap">{text}</span></span></h1>
                  <p>Recent graduate passionate about Software development, Currently working as a Vue Js Developer. Ready to Innovate and Collaborate </p>
                  <button onClick={handleClick}>Let’s Connect <ArrowRightCircle size={25} /></button>
              </div>}
            </TrackVisibility> */}
              <TrackVisibility>
              {({ isVisible }) =>
                <div className={isVisible ? "animate__animated animate__fadeIn" : ""}>
                  {/* ✨ Animated Welcome Back Text ✨ */}
                  <h2 className="typing-text">Welcome back!</h2>

                  <h1>
                    {`Hi! I'm Hariharan, `}
                    <span className="txt-rotate" dataPeriod="1000" data-rotate='[ "Full Stack Java Developer", "Frontend Developer", "Software Developer"]'>
                      <span className="wrap">{text}</span>
                    </span>
                  </h1>
                  <p>Frontend Developer specializing in building modern, responsive user interfaces using Vue,React and Tailwind CSS, with a strong focus on performance, accessibility, and clean UI/UX design,
                     with additional exposure to backend technologies like Spring Boot and MySQL.

                  </p>
                  <button onClick={handleClick}>Let’s Connect <ArrowRightCircle size={25} /></button>
                </div>
              }
            </TrackVisibility>

          </Col>
          <Col xs={12} md={6} xl={5}>
            <TrackVisibility>
              {({ isVisible }) =>
                <div className={isVisible ? "animate__animated animate__zoomIn" : ""}>
                  <img src={headerImg} alt="Header Img"/>
                </div>}
            </TrackVisibility>
          </Col>
        </Row>
      </Container>
    </section>
  )
}